        3: {1: 4}
    }

    # Use Dijkstra's algorithm to find the shortest path
    import heapq
    from typing import Dict, List, Tuple, Optional

    def dijkstra(start: int, end: int, graph: Dict[int, Dict[int, int]]) -> Tuple[List[int], int]:
        # Initialize distances and previous nodes
        distances: Dict[int, int] = {node: float('infinity') for node in graph}
        distances[start] = 0
        previous: Dict[int, Optional[int]] = {node: None for node in graph}

        # Priority queue: (distance, current node)
        priority_queue: List[Tuple[int, int]] = [(0, start)]

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            if current_node == end:
                break

            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph[current_node].items():
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    previous[neighbor] = current_node
                    heapq.heappush(priority_queue, (distance, neighbor))

        # Build the path
        path: List[int] = []
        current_node = end
        while current_node is not None:
            path.append(current_node)
            current_node = previous[current_node]
        path.reverse()

        return path, distances[end]

    path, distance = dijkstra(0, 3, graph)
    return path, distance

