def solution():
    graph = {
        1: [4, 5],
        2: [],
        3: [4, 5, 6],
        4: [1, 3, 6],
        5: [1, 3, 6],
        6: [3, 4, 5]
    }
    colors = ['A', 'B', 'C']
    color_assignment = {}

    def is_valid(vertex, color):
        for neighbor in graph[vertex]:
            if neighbor in color_assignment and color_assignment[neighbor] == color:
                return False
        return True

    def backtrack(vertex):
        if vertex > 6:
            return color_assignment.copy()
        for color in colors:
            if is_valid(vertex, color):
                color_assignment[vertex] = color
                result = backtrack(vertex + 1)
                if result is not None:
                    return result
                del color_assignment[vertex]
        return None

    result = backtrack(1)
    return result if result is not None else {}
```

